// === Tab: mySketch ===
//for #wccChallenge on the theme 'noise'. I assumed most people would be using noise to make
//landscapes or abstract blobby/swirly stuff. So, I decided to try something organic and lifelike
//using my great generative love of openSimplex noise.

//Every aspect of this (the tentacles, the seaweed, the texture, the head) are all shaped by the lovely 
//flowiness of openSimplex. Except the eyes. Those eyes are staring straight at your soul.

//Love octopuses, btw. So alien and amazing.
//If you want to go off on a tangent--> https://www.smithsonianmag.com/science-nature/ten-curious-facts-about-octopuses-7625828/


let texture
let simplex
let seaweeds=[]
let weeds
let weedWiggle= true

function setup() {
	createCanvas(windowWidth, windowHeight);
	texture= createGraphics(width, height)
	weeds= createGraphics(width, height)
	simplex = new OpenSimplexNoise(Date.now());
	pixelDensity(1)
	//texture
	texture.pixelDensity(1)
	texture.loadPixels()
	for(let x=0; x<width; x++){
		for(let y=0; y<height; y+=floor(random(0, 3))){
	var index = (x + y * width)*4;
		let avalue= map(simplex.noise2D(x/800, y/100), -1, 1, 0, 60)
	  texture.pixels[index+0]= 0;
    texture.pixels[index+1]= 0;
    texture.pixels[index+2]= 0;
    texture.pixels[index+3]= avalue;

		}
	}
	texture.updatePixels()
	for(let i=0; i<20; i++){
		seaweeds.push(new seaweed(random(width), random(width/10, height*0.66), random(3, 40)))

	}
	for(let seaweed of seaweeds){
		seaweed.setupShow()
	}


}

function draw() {
	background(240);
	noStroke()
	//print(frameRate())

	if(weedWiggle){
	for(let seaweed of seaweeds){
		seaweed.show()
	}
	} else{
		image(weeds, 0, 0)
	}


	//tentacle placement - function below
	for(let a=PI/4; a<=PI*0.75; a+=PI/16){
	tentacle(width/2+cos(a)*125, height/5-70+sin(a)*150, 350)
}

	//head 
	push()
	translate(width/2, height/5)
	for(let shading=0; shading<=100; shading+=5){
	fill(shading)
	beginShape()
	for(let i=0; i<=TAU; i+=0.1){
		let offsetter= 10-(i/9)
		let xOffset= map(simplex.noise3D(width/2, sin(i), frameCount/100), -1, 1, -offsetter, offsetter)
		let yOffset= map(simplex.noise3D(height/2, cos(i), frameCount/100), -1, 1, -offsetter, offsetter)
		let xr=125-shading*0.8
		let yr=100-shading
		curveVertex(cos(i)*xr+xOffset, sin(i)*yr+yOffset-shading*0.80)
		}
	endShape()
	}

	//eyes
	fill(0)
	ellipse(-80, 0, 40)
	ellipse(80, 0, 40)
	fill(220)
	ellipse(-90, 0, 12, 20)
	ellipse(90, 0, 12, 20)
	pop()




	image(texture, 0, 0)
}

function tentacle(x, y, length){
	push()
	translate(x, y)
	noStroke()
	for(let i=0; i<length; i+=2){
		let xoffset= map(simplex.noise3D(x, i/200, frameCount/1200), -1, 1, -i*2, i*2)
		let yoffset= map(simplex.noise3D(x, i/400, frameCount/3000), -1, 1, -i, i)

			let tw=map(i, 0, length, 50, 0)
			push()
		fill(0, 50)
			translate(xoffset, i+yoffset)
			ellipse(0, 0, tw, tw)
			pop()

	}

	pop()

}


class seaweed {

	constructor(x, length, width){
		this.x=x
		this.length=length
		this.width=width
	}

	show(){
	push()
	let filler =map(this.width, 3, 40, 220, 150)
	fill(filler)
	translate(this.x, height)
	beginShape()
	for(let y=0; y>-this.length; y--){
		let waviness=map(simplex.noise3D(this.x, y/10, frameCount/50), -1, 1, 0, this.width/2)
		curveVertex(waviness, y)
	}
		curveVertex(0, -this.length-10)
	for(let y=-this.length; y<=0; y++){
		let waviness=map(simplex.noise3D(this.x, y/10, frameCount/50), -1, 1, 0, this.width/2)
		curveVertex(-waviness, y)
	}
	endShape()
	pop()
	}	


	setupShow(){
	weeds.push()
	weeds.noStroke()
	let filler =map(this.width, 3, 40, 220, 150)
	weeds.fill(filler)
	weeds.translate(this.x, height)
	weeds.beginShape()
	for(let y=0; y>-this.length; y--){
		let waviness=map(simplex.noise3D(this.x, y/10, frameCount/50), -1, 1, 0, this.width/2)
		weeds.curveVertex(waviness, y)
	}
		weeds.curveVertex(0, -this.length-10)
	for(let y=-this.length; y<=0; y++){
		let waviness=map(simplex.noise3D(this.x, y/10, frameCount/50), -1, 1, 0, this.width/2)
		weeds.curveVertex(-waviness, y)
	}
	weeds.endShape()
	weeds.pop()
	}	

}


function mousePressed(){
	weedWiggle=!weedWiggle

}
